        #region GetSpecialDelete

        public string GetSpecialDelete(Hashtable param)
        {
            string matchHtml = string.Empty;
            int matchid = 0;
            bool IsHasData = true;

            SpecialDeleteBets_Template bets = new SpecialDeleteBets_Template();

            SpecialDeleteBets_Bets_NormalBets_ContentNomalBets_Block normalBet = new SpecialDeleteBets_Bets_NormalBets_ContentNomalBets_Block();
            SpecialDeleteBets_Bets_SpecialBets_ContentSpecialBets_Block specialBet = new SpecialDeleteBets_Bets_SpecialBets_ContentSpecialBets_Block();
            SpecialDeleteBets_Bets_SpecialBets_HeaderSpecialBets_Block headerBet = new SpecialDeleteBets_Bets_SpecialBets_HeaderSpecialBets_Block();

            DbResult rs;

            rs = DbHelper.Execute("DBA_SelBet_BatchMsg", param, DBType.REPORT);

            DataTableCollection lst = rs.ResultSet.Tables;
            int index = 0;
            int countTbl = 0;
            int cntNormalBet = 0, cntDeposit = 0, cntBetDaq = 0, cnt12EU = 0, cntMasterMHC = 0;

            bets.Bets.NormalBets.ContentNomalBets.Clear();
            bets.Bets.SpecialBets.HeaderSpecialBets.Clear();
            bets.Bets.SpecialBets.ContentSpecialBets.Clear();

            cntNormalBet = rs.ResultSet.Tables[0].Rows.Count;//normal bet
            //cntDeposit = rs.ResultSet.Tables[1].Rows.Count;//deposit bet
            //cntBetDaq = rs.ResultSet.Tables[2].Rows.Count;//bet daq
            //cnt12EU = rs.ResultSet.Tables[3].Rows.Count;//bet 12EU
            //cntMasterMHC = rs.ResultSet.Tables[4].Rows.Count;//bet master MHC

            if (cntNormalBet == 0 && cntDeposit == 0 && cntBetDaq == 0 && cnt12EU == 0 && cntMasterMHC == 0)
            {
                IsHasData = false;
                bets.Bets.NormalBets.HeaderNomalBets.DeleteOption.Clear();
                normalBet.DeleteOption.Clear();
            }
            else if (cntNormalBet > 0 && cntDeposit == 0 && cntBetDaq == 0 && cnt12EU == 0 && cntMasterMHC == 0)
            {
                IsHasData = true;
                bets.Bets.NormalBets.HeaderNomalBets.DeleteOption.Clear();
                normalBet.DeleteOption.Clear();
                bets.Bets.no_info.Clear();
            }
            else
            {
                IsHasData = true;
                bets.Bets.no_info.Clear();
            }

            foreach (DataTable item in lst)
            {
                DataRow[] drs = item.Select();

                foreach (DataRow dr in drs)
                {
                    index++;

                    SpecialDeleteRow row = Mapping(dr);

                    if (countTbl == 0) //NormalBet
                    {
                        AssignDatarow(row, index, ref normalBet);
                        bets.Bets.NormalBets.ContentNomalBets.Append(normalBet);
                    }
                    else if (countTbl == 1)//Deposit
                    {
                        if (index == 1)
                        {
                            GetHeaderSpecialBets("Deposit", "#6495ed", SpecialBettype.BetDeposit, ref headerBet);
                            //bets.Bets.SpecialBets.HeaderSpecialBets.Append(headerBet);
                            bets.Bets.SpecialBets.Append(headerBet);
                        }

                        AssignDatarow(row, index, SpecialBettype.BetDeposit, ref specialBet);
                        bets.Bets.SpecialBets.Append(specialBet);
                    }
                    else if (countTbl == 2)//BetDaq
                    {
                        if (index == 1)
                        {
                            GetHeaderSpecialBets("Bet Daq", "#659E17", SpecialBettype.Betdaq, ref headerBet);
                            //bets.Bets.SpecialBets.HeaderSpecialBets.Append(headerBet);
                            bets.Bets.SpecialBets.Append(headerBet);
                        }

                        AssignDatarow(row, index, SpecialBettype.Betdaq, ref specialBet);
                        bets.Bets.SpecialBets.Append(specialBet);
                    }
                    else if (countTbl == 3)//12EU
                    {
                        if (index == 1)
                        {
                            GetHeaderSpecialBets("12EU", "#cc9900", SpecialBettype.Bet12EU, ref headerBet);
                            //bets.Bets.SpecialBets.HeaderSpecialBets.Append(headerBet);
                            bets.Bets.SpecialBets.Append(headerBet);
                        }

                        AssignDatarow(row, index, SpecialBettype.Bet12EU, ref specialBet);
                        bets.Bets.SpecialBets.Append(specialBet);
                    }
                    else if (countTbl == 4)//member of master: MHCEU (105181), MHCRM (118473), MHCUS(105183)
                    {
                        if (index == 1)
                        {
                            GetHeaderSpecialBets("Members belong to Master MHCEU, MHCRM and MHCUS", "#ff8040", SpecialBettype.BetMasterMHC, ref headerBet);
                            //bets.Bets.SpecialBets.HeaderSpecialBets.Append(headerBet);
                            bets.Bets.SpecialBets.Append(headerBet);
                        }

                        AssignDatarow(row, index, SpecialBettype.BetMasterMHC, ref specialBet);
                        bets.Bets.SpecialBets.Append(specialBet);
                    }
                }

                index = 0;
                countTbl++;
            }

            bets.rowcount = cntNormalBet.ToString();
            bets.rowcountDeposit = cntDeposit.ToString();
            bets.rowcountBD = cntBetDaq.ToString();
            bets.rowcount12EU = cnt12EU.ToString();
            bets.rowcountMHC = cntMasterMHC.ToString();

            bool IsFail = false;
            string matchinfo = string.Empty;

            matchinfo = GetMatchInfoById(matchid, ref IsFail);

            bets.MatchInfo = matchinfo;
            if (IsFail)
            {
                bets.Bets.Clear();
                bets.DeleteBetsForm = string.Empty;
            }
            else
            {
                if (IsHasData)
                    bets.DeleteBetsForm = BuildDeleteFormNew(param);
                else
                    bets.DeleteBetsForm = string.Empty;
            }

            return bets.ToString();
        }

        #endregion GetSpecialDelete

        #region GetMatchInfoById

        private string GetMatchInfoById(int matchid, ref bool IsFail)
        {
            IsFail = false;
            string tpl = "";
            List<MatchInfoRow> lst = SpecialDeleteProvider.Instance(DataAccess.DataAccess.DAOClient.Entity).MatchSeById(matchid);
            if (lst.Count == 0)
            {
                IsFail = true;
                tpl = AlertMessage.GetMsg("NO MATCH WITH SUCH MATCH ID", AlertMessage.MsgType.Error);
            }
            else
            {
                _MatchInfo info = new _MatchInfo();

                foreach (MatchInfoRow row in lst)
                {
                    info.MatchCode = row.matchcode;
                    info.Home = CacheRef.GetTeamName(row.homeid) + (row.IsNeutral ? ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "IsNeutral") : string.Empty);
                    info.Away = CacheRef.GetTeamName(row.awayid);
                    info.EventDate = row.eventdate.ToString();
                }
                tpl = info.ToString();
            }

            return tpl;
        }

        #endregion GetMatchInfoById

        #region AssignDatarow

        private void AssignDatarow(SpecialDeleteRow row, int index, ref SpecialDeleteBets_Bets_NormalBets_ContentNomalBets_Block transrow_normal)
        {
            transrow_normal.no = index.ToString();
            transrow_normal.Account = row.username;
            transrow_normal.Refno = row.transid;
            transrow_normal.Bettype = CacheRef.GetBettype(row.bettype);
            transrow_normal.Bet = row.betteam;
            transrow_normal.Odds = IBCUtils.FormatHandler.FormatNumber3(row.odds);
            transrow_normal.OddsType = CacheRef.GetOddsTypeName(row.oddstype);
            transrow_normal.Amount = IBCUtils.FormatHandler.FormatNumber2(row.StakePositiontaking);
            transrow_normal.currency = CacheUtils.GetExchangeName(row.currency);
            switch (row.bettype)
            {
                case 1:
                case 3:
                case 7:
                case 8:
                case 22:
                    transrow_normal.Hdp = IBCUtils.FormatHandler.FormatNumber2(row.hdp2 - row.hdp1);
                    break;

                default:
                    transrow_normal.Hdp = "--";
                    break;
            }

            transrow_normal.TransTime = row.transdate.ToString();
            transrow_normal.HomeScore = row.livehomescore.ToString();
            transrow_normal.AwayScore = row.liveawayscore.ToString();
            transrow_normal.Creator = row.creator;
            transrow_normal.Status = row.status;

            //return transrow_normal;
        }

        #endregion AssignDatarow

        #region AssignDatarow

        private void AssignDatarow(SpecialDeleteRow row, int index, SpecialBettype type, ref SpecialDeleteBets_Bets_SpecialBets_ContentSpecialBets_Block transRowTpl_SB)
        {
            transRowTpl_SB.no = index.ToString();
